/**
 * The open-source motion library, as data.
 *
 * Everything here reads library/catalogue.json and library/blocks.json, which
 * are generated by scripts/build-library.mjs from the vendored upstream
 * repositories. Nothing is fetched at runtime and nothing is invented.
 *
 * The catalogue holds 9 upstream collections normalised to one shape:
 *   prompt | style | technique | skill | case
 * plus the HyperFrames block library, which holds installable motion
 * components rather than text.
 */
import { readFileSync, existsSync } from "node:fs";

export type LibraryKind = "prompt" | "style" | "skill" | "case";
export type LibraryKindFilter = LibraryKind | "all";

export interface LibraryItem {
  id: string;
  collection: string;
  kind: LibraryKind;
  title: string;
  titleZh: string;
  summary: string;
  prompt: string;
  partial: boolean;
  categories: string[];
  tags: string[];
  author: string;
  source: string;
  tools: string[];
  metrics: Record<string, unknown>;
  license: string;
}

export interface LibraryCollection {
  id: string;
  title: string;
  repo: string;
  license: string;
  homepage: string;
  kind: string;
  count: number;
  categories: { slug: string; title: string; description?: string }[];
}

export interface LibraryCategory {
  slug: string;
  count: number;
}

export interface LibraryCatalogue {
  counts: {
    items: number;
    byKind: Record<string, number>;
    blocks: number;
    collections: number;
    categories: number;
  };
  collections: LibraryCollection[];
  categories: LibraryCategory[];
  items: LibraryItem[];
}

export interface LibraryBlock {
  id: string;
  type: string;
  title: string;
  description: string;
  tags: string[];
  author: string | null;
  dimensions: { width: number; height: number } | null;
  duration: number | null;
  /** The block's editable schema: headlines, image slots, speed, colour. */
  variables: {
    id: string;
    type: string;
    role: string | null;
    label: string;
    description: string;
    portrays: string[];
    default: unknown;
    min: number | null;
    max: number | null;
  }[];
  files: { path: string; target: string; type: string }[];
  license: string;
}

export interface BlocksFile {
  generated: string;
  source: string;
  count: number;
  tags: { slug: string; count: number }[];
  blocks: LibraryBlock[];
}

let catalogueCache: LibraryCatalogue | null = null;
let blocksCache: BlocksFile | null = null;

export function loadCatalogue(path: string): LibraryCatalogue {
  if (catalogueCache) return catalogueCache;
  if (!existsSync(path)) {
    throw new Error(
      `The motion library is missing at ${path}. Run: node scripts/build-library.mjs`,
    );
  }
  catalogueCache = JSON.parse(readFileSync(path, "utf8")) as LibraryCatalogue;
  return catalogueCache;
}

export function loadBlocks(path: string): BlocksFile {
  if (blocksCache) return blocksCache;
  if (!existsSync(path)) {
    throw new Error(
      `The block library is missing at ${path}. Run: node scripts/build-library.mjs`,
    );
  }
  blocksCache = JSON.parse(readFileSync(path, "utf8")) as BlocksFile;
  return blocksCache;
}

/* ------------------------------------------------------------------ queries */

export interface BrowseArgs {
  collection?: string;
  kind?: LibraryKindFilter;
  category?: string;
  query?: string;
  tag?: string;
  license?: string;
  limit?: number;
  offset?: number;
}

export interface BrowseResult {
  total: number;
  returned: number;
  offset: number;
  limit: number;
  items: LibraryItem[];
}

/**
 * Browse the library. Every filter is optional and they combine with AND.
 * A query matches the title, summary, prompt text or tags, case-insensitively.
 */
export function browse(catalogue: LibraryCatalogue, args: BrowseArgs): BrowseResult {
  const limit = Math.min(Math.max(args.limit ?? 20, 1), 100);
  const offset = Math.max(args.offset ?? 0, 0);
  const q = args.query?.trim().toLowerCase();

  const filtered = catalogue.items.filter((item) => {
    if (args.collection && item.collection !== args.collection) return false;
    if (args.kind && args.kind !== "all" && item.kind !== args.kind) return false;
    if (args.category && !item.categories.includes(args.category)) return false;
    if (args.tag && !item.tags.includes(args.tag)) return false;
    if (args.license && item.license !== args.license) return false;
    if (q) {
      const hay = `${item.title}\n${item.titleZh}\n${item.summary}\n${item.tags.join(" ")}\n${item.categories.join(" ")}\n${item.prompt}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  return {
    total: filtered.length,
    returned: Math.min(limit, Math.max(filtered.length - offset, 0)),
    offset,
    limit,
    items: filtered.slice(offset, offset + limit),
  };
}

/**
 * Categories, with counts, optionally narrowed to one collection or kind.
 * This is the map an agent or a human reads before choosing anything.
 */
export function listCategories(
  catalogue: LibraryCatalogue,
  filters: { collection?: string; kind?: LibraryKindFilter; minCount?: number } = {},
): LibraryCategory[] {
  const min = filters.minCount ?? 1;
  const counts = new Map<string, number>();
  for (const item of catalogue.items) {
    if (filters.collection && item.collection !== filters.collection) continue;
    if (filters.kind && filters.kind !== "all" && item.kind !== filters.kind) continue;
    for (const c of item.categories) counts.set(c, (counts.get(c) ?? 0) + 1);
  }
  return [...counts.entries()]
    .filter(([, n]) => n >= min)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([slug, count]) => ({ slug, count }));
}

export function getItem(catalogue: LibraryCatalogue, id: string): LibraryItem | undefined {
  return catalogue.items.find((i) => i.id === id);
}

/* ------------------------------------------------------- style matching ---- */

const STOP = new Set([
  "a", "an", "the", "of", "for", "and", "or", "to", "in", "on", "with", "as",
  "at", "by", "from", "is", "it", "this", "that", "be", "are", "make", "create",
  "video", "animation", "animated", "motion", "graphics", "clip", "film", "short",
]);

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s-]+/gu, " ")
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOP.has(w));
}

/**
 * Rank the style recipes in the library against a piece of text.
 * A style recipe is a named look plus the wording that produces it, so a
 * token overlap against the recipe and its title is a fair ranking signal.
 */
export function matchStyles(
  catalogue: LibraryCatalogue,
  text: string,
  limit = 5,
): { item: LibraryItem; score: number }[] {
  const words = new Set(tokenize(text));
  if (!words.size) return [];
  const styles = catalogue.items.filter((i) => i.kind === "style");

  return styles
    .map((item) => {
      const hay = `${item.title} ${item.summary} ${item.prompt} ${item.tags.join(" ")}`;
      const hayWords = new Set(tokenize(hay));
      let overlap = 0;
      for (const w of words) if (hayWords.has(w)) overlap += 1;
      // Weight the title and tags far above the prose body.
      const titleWords = new Set(tokenize(`${item.title} ${item.tags.join(" ")}`));
      let titleOverlap = 0;
      for (const w of words) if (titleWords.has(w)) titleOverlap += 1;
      const score = overlap + titleOverlap * 3;
      return { item, score };
    })
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}
